        treatment_protocol="鎮静・神経ブロック(耳介眼瞼神経、眼窩上神経)下での眼科検査。角膜潰瘍に局所抗菌薬：クロラムフェニコール、シプロフロキサシン、または三種混合抗菌薬。毛様体痙攣・疼痛に局所アトロピン 1%。頻回投薬のための眼瞼下洗浄システム。ぶどう膜炎に全身性NSAIDs(フルニキシンメグルミン 1.1 mg/kg IV)。局所コルチコステロイドは非潰瘍性疾患にのみ使用。免疫介在性角膜炎にシクロスポリン。末期の疼痛性眼には眼球摘出。紫外線防護のフライマスク。",
